  day: day.map((value, i) => ({ label: DAYS[i] ?? "", shortLabel: DAYS[i]?.charAt(0), value })),
  week: week.map((value, i) => ({
    label: WEEKS[i] ?? "",
    shortLabel: WEEKS[i]?.split(" ")[1],
    fullLabel: `Week of ${WEEKS[i]}`,
