// EXPORT
// ==========================================
/** The selected period's overview series as a CSV download. */
function downloadCsv(metrics: DashboardMetric[], period: DashboardPeriod) {
  const longest = metrics.reduce<DashboardPoint[]>(
    (best, metric) => ((metric.series[period]?.length ?? 0) > best.length ? metric.series[period] ?? [] : best),
    [],
  );
  const escape = (value: string) => `"${value.replace(/"/g, '""')}"`;
  const header = ["Period", ...metrics.map((metric) => metric.label)].map(escape).join(",");
  const rows = longest.map((point, index) =>
    [
      escape(point.fullLabel ?? point.label),
      ...metrics.map((metric) => String(metric.series[period]?.[index]?.value ?? "")),
    ].join(","),
  );
  const blob = new Blob(["﻿" + [header, ...rows].join("\n")], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `dashboard-${period}.csv`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

/** "So far today: 12 new users, 4 messages and $1,240 in revenue." */
function describeToday(metrics: DashboardMetric[]) {
  const parts = metrics.flatMap((metric) => {
    const points = metric.series.day ?? [];
    const value = points[points.length - 1]?.value ?? 0;
    if (!value) return [];
    if (metric.currency) return [`${formatMoney(value, metric.currency)} in ${metric.label.toLowerCase()}`];
    return [`${formatNumber(value)} ${metric.noun ? plural(value, metric.noun) : metric.label.toLowerCase()}`];
  });
  if (!parts.length) return "Nothing new yet today.";
  const list =
    parts.length < 2 ? parts[0] : `${parts.slice(0, -1).join(", ")} and ${parts[parts.length - 1]}`;
  return `So far today: ${list}.`;
}

// ==========================================
// SECTION
// ==========================================
/**
 * An admin dashboard home: a greeting with all-time totals, a period switch,
 * an overview chart with a tab per metric, the activity feed, traffic
 * sources, visitors by country and the top authors. Every number comes from
 * props, so wire it to your API and the layout takes care of itself.
 */
export function Dashboard({
  userName,
  summary,
  totals = [],
  metrics = [],
  activity = [],
  sources,
  signUps,
  countries,
  authors,
  defaultPeriod = "month",
  onExport,
  links = {},
  linkComponent = "a",
  now: fixedNow,
  className,
  style,
  ...props
}: DashboardProps) {
  const [period, setPeriod] = useState<DashboardPeriod>(defaultPeriod);
  const now = useNow(fixedNow);

  return (
    <section
      aria-label="Dashboard"
      className={cn(
        "relative isolate w-full overflow-hidden rounded-[28px] p-4 text-foreground sm:p-6 lg:p-8",
        ROOT_TOKENS,
        className,
      )}
      style={{ ...CANVAS_STYLE, ...style }}
      {...props}
    >
      <div className="space-y-6 lg:space-y-8">
        <DashboardHeader
          userName={userName}
          summary={summary ?? describeToday(metrics)}
          totals={totals}
          now={now}
        />

        <div className="flex flex-wrap items-center justify-between gap-3">
          <ToggleGroup
            type="single"
            variant="segmented"
            value={period}
            onValueChange={(next) => {
              if (next === "day" || next === "week" || next === "month") setPeriod(next);
            }}
            aria-label="Reporting period"
          >
            {PERIODS.map((option) => (
              <ToggleGroupItem key={option.value} value={option.value}>
                {option.label}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
          <button
            type="button"
            onClick={() => (onExport ? onExport(period) : downloadCsv(metrics, period))}
            className={cn(
              "inline-flex h-10 items-center gap-2 rounded-full bg-primary px-5 text-sm font-medium text-primary-foreground shadow-sm transition-[filter] hover:brightness-110",
              FOCUS,
            )}
          >
            <Download className="size-4" aria-hidden="true" />
            Export
          </button>
        </div>

        <div className="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-12 xl:gap-6">
          {/* Side by side, the overview sets the row height: `contain: size`
              stops the activity feed from stretching the row, so it fills the
              row and scrolls instead. */}
          <OverviewPanel metrics={metrics} period={period} className="md:col-span-2 xl:col-span-8" />
          <ActivityPanel
            activity={activity}
            now={now}
            href={links.activity}
            linkComponent={linkComponent}
            className="md:col-span-2 xl:col-span-4 xl:[contain:size]"
          />
          <TrafficSourcesPanel
            shares={sources?.[period]}
            signUps={signUps?.[period]}
            period={period}
            href={links.traffic}
            linkComponent={linkComponent}
            className="xl:col-span-4"
          />
          <CountriesPanel
            shares={countries?.[period]}
            period={period}
            href={links.countries}
            linkComponent={linkComponent}
            className="xl:col-span-4"
          />
          <TopAuthorsPanel
            authors={authors?.[period] ?? []}
            period={period}
            href={links.authors}
            linkComponent={linkComponent}
            className="md:col-span-2 xl:col-span-4"
          />
        </div>
      </div>
    </section>
  );
}

export default Dashboard;

"use client";

import { cn } from "@/lib/utils";
import { useId, useState } from "react";

// ==========================================
// DYNAMIC THEME ENGINE
// ==========================================
export type ChartColor =
  | "indigo"
  | "rose"
  | "emerald"
  | "zinc"
  | "amber"
  | "blue"
  | string;
export type ChartType =
  | "bar"
  | "line"
  | "pie"
  | "donut"
  /** A categorical donut with a legend beside it; hover either to read a share. */
  | "donut-legend"
  /** One horizontal bar split into shares, legend below. */
  | "stacked-bar";

const colorMap: Record<string, string> = {
  indigo: "#4f46e5",
  rose: "#e11d48",
  emerald: "#10b981",
  zinc: "#3f3f46",
  amber: "#f59e0b",
  blue: "#3b82f6",
};

const getThemeColor = (color: string) => {
  if (color.startsWith("#") || color.startsWith("var(")) return color;
  return colorMap[color] || "var(--primary)";
};

const inkOn = (color: string) =>
  color === "var(--primary)" ? "text-primary-foreground" : "text-white";

/**
 * Categorical palette for the legend charts, where every share needs its own
 * hue rather than a shade of one. The theme accent leads; the grey at the end
 * is what an "Other" bucket lands on when there are five shares.
 */
const CATEGORICAL = [
  "var(--primary)",
  "#0d9488",
  "#d97706",
  "#e11d48",
  "#a1a1aa",
];

// ==========================================
// TYPES & PROPS
// ==========================================
export interface ChartDataPoint {
  label: string;
  value: number;
  /** Own colour for this share in `donut-legend` and `stacked-bar`. */
  color?: string;
}

export interface ChartBlockProps {
  data: ChartDataPoint[];
  type?: ChartType;
  color?: ChartColor;
  /**
   * Fixed pixel height. Defaults to 300 for the axis charts; the legend
   * charts (`donut-legend`, `stacked-bar`) size to their content unless set.
   */
  height?: number;
  className?: string;
  valuePrefix?: string;
  valueSuffix?: string;
  showGrid?: boolean;
  showArea?: boolean;
  /**
   * Palette for the legend charts, one colour per share in order. A point's
   * own `color` wins over it. Defaults to the theme accent and four hues.
   */
  colors?: string[];
  /** `donut-legend`: caption under the centre value at rest, e.g. "top reason". */
  centerLabel?: string;
  /** `donut-legend`: caption under the centre value while a share is hovered. */
  hoverLabel?: string;
}

// ==========================================
// MAIN COMPONENT EXPORT
// ==========================================
export function ChartBlock({
  data,
  type = "bar",
  color = "var(--primary)",
  height,
  className,
  valuePrefix = "",
  valueSuffix = "",
  showGrid = true,
  showArea = true,
  colors = CATEGORICAL,
  centerLabel = "largest",
  hoverLabel = "share",
}: ChartBlockProps) {
  const themeColor = getThemeColor(color);
  const isLegendChart = type === "donut-legend" || type === "stacked-bar";
  // Every share gets a colour: its own, else the palette in order, wrapping.
  const shareColor = (d: ChartDataPoint, i: number) =>
    getThemeColor(d.color ?? colors[i % colors.length] ?? "primary");

  return (
    <div
      className={cn("relative w-full", className)}
      style={{ height: height ?? (isLegendChart ? undefined : 300) }}
    >
      {/* NATIVE CSS ANIMATIONS */}
      <style>{`
        @keyframes drawLine { from { clip-path: inset(-8px 100% -8px -8px); } to { clip-path: inset(-8px -8px -8px -8px); } }
        @keyframes growUp { from { transform: scaleY(0); opacity: 0; } to { transform: scaleY(1); opacity: 1; } }
        @keyframes fadeUp { from { transform: translateY(10px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .animate-draw { animation: drawLine 1.5s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
        .animate-grow { animation: growUp 1s cubic-bezier(0.22, 1, 0.36, 1) forwards; transform-origin: bottom; }
        .animate-fade { animation: fadeUp 1s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
      `}</style>

      {type === "bar" && (
        <BarChart
          data={data}
          color={themeColor}
          prefix={valuePrefix}
          suffix={valueSuffix}
          showGrid={showGrid}
        />
      )}

      {type === "line" && (
        <SmoothLineChart
          data={data}
          color={themeColor}
          prefix={valuePrefix}
          suffix={valueSuffix}
          showGrid={showGrid}
          showArea={showArea}
        />
      )}

      {(type === "pie" || type === "donut") && (
        <CircularChart
          data={data}
          type={type}
          color={themeColor}
          prefix={valuePrefix}
          suffix={valueSuffix}
        />
      )}

      {type === "donut-legend" && (
        <DonutLegendChart
          data={data}
          shareColor={shareColor}
          prefix={valuePrefix}
          suffix={valueSuffix}
          centerLabel={centerLabel}
          hoverLabel={hoverLabel}
        />
      )}

      {type === "stacked-bar" && (
        <StackedBarChart
          data={data}
          shareColor={shareColor}
          prefix={valuePrefix}
          suffix={valueSuffix}
        />
      )}
    </div>
  );
}

