// ==========================================
// 2. SVG SMOOTH CURVE CHART (Line + Area Merge)
// ==========================================
function SmoothLineChart({
  data,
  color,
  prefix,
  suffix,
  showGrid,
  showArea,
}: {
  data: ChartDataPoint[];
  color: string;
  prefix: string;
  suffix: string;
  showGrid: boolean;
  showArea: boolean;
}) {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const maxVal = Math.max(...data.map((d) => d.value), 1);
  // An id that is valid whatever the colour is: `var(--primary)` (the
  // default) is not a legal fragment for `url(#…)`, which left the area black.
  const cleanColorId = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  // Calculate X/Y percentages for the data
  const points = data.map((d, i) => ({
    x: (i / Math.max(data.length - 1, 1)) * 100,
    y: 100 - (d.value / maxVal) * 100,
    label: d.label,
    value: d.value,
  }));

  // Mathematical cubic bezier curve generator for a premium SaaS look
  const createSmoothPath = (pts: { x: number; y: number }[]) => {
    const first = pts[0];
    if (!first) return "";
    let d = `M ${first.x} ${first.y}`;
    for (let i = 1; i < pts.length; i++) {
      const prev = pts[i - 1];
      const curr = pts[i];
      if (!prev || !curr) continue;
      const cpX = (prev.x + curr.x) / 2; // Midpoint easing
      d += ` C ${cpX} ${prev.y}, ${cpX} ${curr.y}, ${curr.x} ${curr.y}`;
    }
    return d;
  };

  const smoothPath = createSmoothPath(points);
  const areaPath = `${smoothPath} L 100 100 L 0 100 Z`;

  return (
    <div className="relative w-full h-full pt-6 pb-8 pl-12 pr-4 animate-fade">
      {/* Background Grid */}
      <div className="absolute inset-0 top-6 bottom-8 left-12 right-4 flex flex-col justify-between pointer-events-none z-0">
        {[1, 0.5, 0].map((ratio, i) => (
          <div key={i} className="flex items-center w-full relative h-0">
            <span className="absolute -left-3 -translate-x-full text-[10px] font-medium text-muted-foreground">
              {prefix}
              {Math.round(maxVal * ratio)}
              {suffix}
            </span>
            {showGrid && (
              <div className="w-full border-t border-dashed border-border" />
            )}
          </div>
        ))}
      </div>

      {/* Vector Graphics. The draw-in is a left-to-right clip reveal rather
          than a stroke-dasharray sweep: with a non-scaling stroke the dash
          pattern is measured in screen pixels, not pathLength units, so a
          dashed draw cut the line into pieces whose count changed with width. */}
      <svg
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
        className="absolute inset-0 top-6 bottom-8 left-12 right-4 w-[calc(100%-64px)] h-[calc(100%-56px)] overflow-visible z-10 animate-draw"
      >
        <defs>
          <linearGradient
            id={`area-grad-${cleanColorId}`}
            x1="0"
            y1="0"
            x2="0"
            y2="1"
          >
            <stop offset="0%" stopColor={color} stopOpacity="0.35" />
            <stop offset="100%" stopColor={color} stopOpacity="0.0" />
          </linearGradient>
        </defs>

        {/* Optional Area Fill */}
        {showArea && (
          <path
            d={areaPath}
            fill={`url(#area-grad-${cleanColorId})`}
            className="animate-fade"
          />
        )}

        {/* Animated Line Stroke */}
        <path
          d={smoothPath}
          fill="none"
          stroke={color}
          strokeWidth="2.5"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="drop-shadow-sm"
          style={{ vectorEffect: "non-scaling-stroke" }}
        />
      </svg>

      {/* HTML Interaction Overlay (Perfectly round dots that never squash) */}
      <div className="absolute inset-0 top-6 bottom-8 left-12 right-4 z-20">
        {points.map((p, i) => (
          <div
            key={i}
            className="absolute top-0 bottom-0 cursor-crosshair group"
            style={{
              left: `${p.x}%`,
              width: `${100 / Math.max(points.length - 1, 1)}%`,
              transform: "translateX(-50%)",
            }}
            onMouseEnter={() => setHoveredIndex(i)}
            onMouseLeave={() => setHoveredIndex(null)}
          >
            {/* HTML Dot positioned accurately over the SVG path */}
            <div
              className={cn(
                "absolute w-3 h-3 rounded-full bg-background border-2 transition-all duration-200 pointer-events-none shadow-sm",
                hoveredIndex === i
                  ? "scale-100 opacity-100"
                  : "scale-50 opacity-0",
              )}
              style={{
                top: `${p.y}%`,
                left: "50%",
                transform: "translate(-50%, -50%)",
                borderColor: color,
              }}
            >
              {/* Tooltip */}
              <div
                className={cn(
                  "absolute -top-10 left-1/2 -translate-x-1/2 flex flex-col items-center transition-all duration-200",
                  hoveredIndex === i
                    ? "opacity-100 scale-100"
                    : "opacity-0 scale-95",
                )}
              >
                <div
                  className={cn(inkOn(color), "px-3 py-1.5 rounded-lg shadow-xl text-xs font-semibold whitespace-nowrap text-center")}
                  style={{ backgroundColor: color }}
                >
                  <div className="text-[10px] opacity-80 uppercase tracking-wider font-semibold">
                    {p.label}
                  </div>
                  <div>
                    {prefix}
                    {p.value}
                    {suffix}
                  </div>
                </div>
                <div className="w-2 h-2 rotate-45 -mt-1" style={{ backgroundColor: color }} />
              </div>
            </div>

            {/* X-Axis Label */}
            <span
              className={cn(
                "absolute -bottom-6 left-1/2 -translate-x-1/2 text-[10px] font-medium whitespace-nowrap transition-colors",
                hoveredIndex === i
                  ? "text-foreground font-semibold"
                  : "text-muted-foreground",
              )}
            >
              {p.label}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ==========================================
// 3. SVG STROKE-DASHARRAY CHART (Pie/Donut)
// ==========================================
function CircularChart({
  data,
  type,
  color,
  prefix,
  suffix,
}: {
  data: ChartDataPoint[];
  type: "pie" | "donut";
  color: string;
  prefix: string;
  suffix: string;
}) {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);

  const total = data.reduce((sum, d) => sum + d.value, 0);
  const radius = type === "pie" ? 25 : 40;
  const strokeWidth = type === "pie" ? 50 : 20;
  const circumference = 2 * Math.PI * radius;

  // Each slice starts where the previous one ended. Precomputed rather than
  // accumulated in a mutable variable inside map(), so the mapper stays pure.
  const sliceRatios = data.map((d) => d.value / (total || 1));
  const startRatios: number[] = [];
  sliceRatios.reduce((acc, ratio) => {
    startRatios.push(acc);
    return acc + ratio;
  }, 0);

  // Map data to stroke dashes
  const slices = data.map((d, i) => {
    const sliceRatio = sliceRatios[i] ?? 0;
    const startRatio = startRatios[i] ?? 0;
    const strokeDasharray = `${sliceRatio * circumference} ${circumference}`;
    const strokeDashoffset = -(startRatio * circumference);
    const endOffset = (startRatio + sliceRatio) * circumference;

    const midAngle =
      ((endOffset - (sliceRatio * circumference) / 2) / circumference) *
        Math.PI *
        2 -
      Math.PI / 2;
    const tooltipRadius = type === "pie" ? 30 : 40;

    // Convert polar to cartesian for the tooltip
    const tx = 50 + tooltipRadius * Math.cos(midAngle);
    const ty = 50 + tooltipRadius * Math.sin(midAngle);

    return {
      ...d,
      strokeDasharray,
      strokeDashoffset,
      opacity: 1 - i * 0.15,
      tx,
      ty,
    };
  });
  const hovered = hoveredIndex === null ? undefined : slices[hoveredIndex];

  return (
    <div className="relative w-full h-full flex items-center justify-center animate-fade">
      {/* 1:1 Aspect Ratio Container forces perfect circles */}
      <div className="relative aspect-square h-full max-h-[300px]">
        <svg
          viewBox="0 0 100 100"
          className="w-full h-full overflow-visible -rotate-90"
        >
          {slices.map((slice, i) => (
            <circle
              key={i}
              cx="50"
              cy="50"
              r={radius}
              fill="none"
              stroke={color}
              strokeWidth={strokeWidth}
              strokeDasharray={slice.strokeDasharray}
              strokeDashoffset={slice.strokeDashoffset}
              className={cn(
                "transition-all duration-300 cursor-crosshair",
                hoveredIndex !== null && hoveredIndex !== i
                  ? "opacity-30"
                  : "opacity-100",
              )}
              style={{ opacity: slice.opacity }}
              onMouseEnter={() => setHoveredIndex(i)}
              onMouseLeave={() => setHoveredIndex(null)}
            />
          ))}

          {/* Inner ring to give Donut a sharp edge */}
          {type === "donut" && (
            <circle
              cx="50"
              cy="50"
              r={radius - strokeWidth / 2}
              fill="none"
              stroke="currentColor"
              strokeWidth="0.5"
              className="text-border pointer-events-none"
            />
          )}
        </svg>

        {/* Tooltip Overlay */}
        {hovered && (
          <div
            className="absolute z-50 pointer-events-none animate-in fade-in zoom-in-95 duration-200 flex flex-col items-center"
            style={{
              left: `${hovered.tx}%`,
              top: `${hovered.ty}%`,
              transform: "translate(-50%, -50%)",
            }}
          >
            <div
              className={cn(inkOn(color), "px-3 py-1.5 rounded-lg shadow-xl text-xs font-semibold whitespace-nowrap text-center")}
              style={{ backgroundColor: color }}
            >
              <div className="text-[10px] opacity-80 uppercase tracking-wider font-semibold">
                {hovered.label}
              </div>
              <div>
                {prefix}
                {hovered.value}
                {suffix}
              </div>
            </div>
          </div>
        )}

        {/* Donut Center Total Label */}
        {type === "donut" && (
          <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
            <span className="text-xs font-medium text-muted-foreground">Total</span>
            <span className="text-xl font-semibold text-foreground">
              {prefix}
              {total}
              {suffix}
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

// ==========================================
// 4. DONUT + LEGEND (categorical shares, hover either side)
// ==========================================
function DonutLegendChart({
  data,
  shareColor,
  prefix,
  suffix,
  centerLabel,
  hoverLabel,
}: {
  data: ChartDataPoint[];
  shareColor: (d: ChartDataPoint, i: number) => string;
  prefix: string;
  suffix: string;
  centerLabel: string;
  hoverLabel: string;
}) {
  const [active, setActive] = useState<number | null>(null);
  const total = data.reduce((sum, d) => sum + d.value, 0) || 1;
  const R = 38;
  const C = 2 * Math.PI * R;
  const GAP = 2; // surface gap between segments, in viewBox units

  // Where each segment starts, precomputed so the mapper stays pure.
  const starts: number[] = [];
  data.reduce((acc, d) => {
    starts.push(acc);
    return acc + (C * d.value) / total;
  }, 0);

  // The centre reads the hovered share; at rest, the largest one.
  const largest = data.reduce((best, d, i) => (d.value > (data[best]?.value ?? -Infinity) ? i : best), 0);
  const shown = data[active ?? largest];

  return (
    <div className="flex flex-col items-center gap-5 animate-fade sm:flex-row">
      <div className="relative size-36 shrink-0">
        <svg viewBox="0 0 100 100" className="size-full -rotate-90" role="img" aria-label="Share of the whole by category">
          {data.map((d, i) => {
            const length = (C * d.value) / total;
            return (
              <circle
                key={d.label}
                cx="50"
                cy="50"
                r={R}
                fill="none"
                stroke={shareColor(d, i)}
                strokeWidth={active === i ? 16 : 14}
                strokeDasharray={`${Math.max(0, length - GAP)} ${C}`}
                strokeDashoffset={-(starts[i] ?? 0)}
                onMouseEnter={() => setActive(i)}
                onMouseLeave={() => setActive(null)}
                className={cn(
                  "cursor-pointer transition-[stroke-width,opacity] duration-200",
                  active !== null && active !== i && "opacity-40",
                )}
              />
            );
          })}
        </svg>
        {shown && (
          <div className="absolute inset-0 grid place-items-center text-center">
            <div>
              <p className="text-xl font-semibold tabular-nums text-foreground">
                {prefix}
                {shown.value}
                {suffix}
              </p>
              <p className="text-[10px] text-muted-foreground">{active === null ? centerLabel : hoverLabel}</p>
            </div>
          </div>
        )}
      </div>
      <ul className="min-w-0 flex-1 space-y-2 text-sm">
        {data.map((d, i) => (
          <li
            key={d.label}
            onMouseEnter={() => setActive(i)}
            onMouseLeave={() => setActive(null)}
            className={cn(
              "flex items-start gap-2.5 transition-opacity",
              active !== null && active !== i && "opacity-50",
            )}
          >
            <span
              className="mt-1.5 size-2.5 shrink-0 rounded-full"
              style={{ backgroundColor: shareColor(d, i) }}
            />
            <span className="min-w-0 flex-1 leading-snug">{d.label}</span>
            <span className="font-medium tabular-nums">
              {prefix}
              {d.value}
              {suffix}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

// ==========================================
// 5. STACKED BAR (one bar split into shares, legend below)
// ==========================================
function StackedBarChart({
  data,
  shareColor,
  prefix,
  suffix,
}: {
  data: ChartDataPoint[];
  shareColor: (d: ChartDataPoint, i: number) => string;
  prefix: string;
  suffix: string;
}) {
  const total = data.reduce((sum, d) => sum + d.value, 0) || 1;
  return (
    <div className="animate-fade">
      <div className="flex h-8 gap-0.5 overflow-hidden rounded-lg" role="img" aria-label="Share of the whole by category">
        {data.map((d, i) => (
          <div
            key={d.label}
            style={{ width: `${(d.value / total) * 100}%`, backgroundColor: shareColor(d, i) }}
            title={`${d.label} ${prefix}${d.value}${suffix}`}
            className="h-full first:rounded-l-lg last:rounded-r-lg"
          />
        ))}
      </div>
      <ul className="mt-3 flex flex-wrap gap-x-4 gap-y-1.5 text-xs">
        {data.map((d, i) => (
          <li key={d.label} className="flex items-center gap-1.5">
            <span className="size-2 rounded-full" style={{ backgroundColor: shareColor(d, i) }} />
            <span className="text-muted-foreground">{d.label}</span>
            <span className="font-medium tabular-nums">
              {prefix}
              {d.value}
              {suffix}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import React, {
  createContext,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";

// ==========================================
// 1. CONTEXT
// ==========================================
interface PopoverContextType {
  open: boolean;
  setOpen: React.Dispatch<React.SetStateAction<boolean>>;
  /**
   * The trigger node itself, held in state rather than a ref. A ref shared
   * through context makes every read of this context a ref read during render;
   * a plain node lets the content position and portal itself without one.
   */
  trigger: HTMLDivElement | null;
  setTrigger: React.Dispatch<React.SetStateAction<HTMLDivElement | null>>;
}
const PopoverContext = createContext<PopoverContextType | undefined>(undefined);

// ==========================================
// 2. ROOT COMPONENT
// ==========================================
export interface PopoverProps {
  children: React.ReactNode;
}

export function Popover({ children }: PopoverProps) {
  const [open, setOpen] = useState(false);
  const [trigger, setTrigger] = useState<HTMLDivElement | null>(null);

  return (
    <PopoverContext.Provider value={{ open, setOpen, trigger, setTrigger }}>
      {children}
    </PopoverContext.Provider>
  );
}

// ==========================================
// 3. TRIGGER
// ==========================================
export interface PopoverTriggerProps
  extends React.HTMLAttributes<HTMLDivElement> {
  asChild?: boolean;
}

export function PopoverTrigger({
  children,
  className,
  ...props
}: PopoverTriggerProps) {
  const context = useContext(PopoverContext);
  if (!context) throw new Error("PopoverTrigger must be used within a Popover");

  const { open, setOpen, setTrigger } = context;

  const handleClick = (e: React.MouseEvent) => {
    // Prevent event bubbling if placed inside another clickable element
    e.stopPropagation();
    setOpen((prev) => !prev);
  };

  return (
    <div
      ref={setTrigger}
      onClick={handleClick}
      className={cn("inline-block", className)}
      role="button"
      tabIndex={0}
      aria-haspopup="dialog"
      aria-expanded={open}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          setOpen((prev) => !prev);
        }
      }}
      {...props}
    >
      {children}
    </div>
  );
}

// ==========================================
// 4. CONTENT (Portal Renderer)
// ==========================================
export interface PopoverContentProps
  extends React.HTMLAttributes<HTMLDivElement> {
  side?: "top" | "right" | "bottom" | "left";
  align?: "start" | "center" | "end";
  sideOffset?: number;
  /**
   * Flip to the opposite side and shift the panel back into view when the
   * preferred placement would overflow the viewport. Set to false to pin the
   * panel to `side`/`align` even when it gets cropped.
   */
  avoidCollisions?: boolean;
  /** Minimum gap (px) kept between the panel and the viewport edges. */
  collisionPadding?: number;
}

const OPPOSITE_SIDE = {
  top: "bottom",
  bottom: "top",
  left: "right",
  right: "left",
} as const;

// `max` drops below `min` when the panel is larger than the viewport; pin to
// `min` there so the panel starts at the top/left edge instead of jumping past it.
const clamp = (value: number, min: number, max: number) =>
  Math.max(min, Math.min(value, Math.max(min, max)));

type Side = NonNullable<PopoverContentProps["side"]>;

// Where the panel ended up, in document coordinates. `null` while unmeasured:
// the panel is mounted invisibly, measured, then shown in the same frame.
type Placement = { top: number; left: number; side: Side };

// The entrance grows out of the trigger's edge: a panel below the button
// scales from its own top edge and slides down a touch, and so on.
const ENTER_FROM_SIDE: Record<Side, string> = {
  bottom: "origin-top slide-in-from-top-2",
  top: "origin-bottom slide-in-from-bottom-2",
  left: "origin-right slide-in-from-right-2",
  right: "origin-left slide-in-from-left-2",
};

export function PopoverContent({
  side = "bottom",
  align = "center",
  sideOffset = 8,
  avoidCollisions = true,
  collisionPadding = 8,
  className,
  children,
  ...props
}: PopoverContentProps) {
  const context = useContext(PopoverContext);
  if (!context) throw new Error("PopoverContent must be used within a Popover");

  const { open, setOpen, trigger: triggerEl } = context;
  const [placement, setPlacement] = useState<Placement | null>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  // Forget the last position on close. This component stays mounted while
  // closed, so without this a reopen would paint one frame at the stale
  // coordinates (from before a scroll, or from a different `side`) and then
  // jump next to the trigger. Adjusted while rendering, when `open` changes,
  // rather than in an effect.
  const [prevOpen, setPrevOpen] = useState(open);
  if (open !== prevOpen) {
    setPrevOpen(open);
    if (!open) setPlacement(null);
  }

  // Handle Position Updates. A layout effect runs before the browser paints,
  // so the first visible frame is already in the right place — a plain effect
  // would paint first and reposition afterwards, which reads as a jump.
  useLayoutEffect(() => {
    if (!open || !triggerEl || !contentRef.current) return;

    // Resolve the document/window the trigger actually lives in, so the
    // popover works when rendered inside an iframe (e.g. docs device preview).
    const doc = triggerEl.ownerDocument;
    const win = doc.defaultView ?? window;

    const updatePosition = () => {
      const contentEl = contentRef.current;
      if (!triggerEl || !contentEl) return;

      const viewportWidth = doc.documentElement.clientWidth || win.innerWidth;
      const viewportHeight = doc.documentElement.clientHeight || win.innerHeight;
      const padding = avoidCollisions ? collisionPadding : 0;
      const trigger = triggerEl.getBoundingClientRect();

      // The panel's uncapped size, read from the scroll box. Clearing the caps
      // and re-measuring would resize the element on every scroll frame and
      // re-trigger the ResizeObserver below.
      const chromeY = contentEl.offsetHeight - contentEl.clientHeight;
      const chromeX = contentEl.offsetWidth - contentEl.clientWidth;
      const naturalHeight = contentEl.scrollHeight + chromeY;
      const naturalWidth = contentEl.scrollWidth + chromeX;

      // Room between each trigger edge and the viewport edge, already minus the
      // gap the panel keeps off the trigger — so this is the space the panel can
      // occupy WITHOUT covering the control that opened it.
      const space = {
        top: trigger.top - padding - sideOffset,
        bottom: viewportHeight - trigger.bottom - padding - sideOffset,
        left: trigger.left - padding - sideOffset,
        right: viewportWidth - trigger.right - padding - sideOffset,
      };

      let resolvedSide = side;
      if (avoidCollisions) {
        const wantsVertical = side === "top" || side === "bottom";
        const needed = wantsVertical ? naturalHeight : naturalWidth;
        const flipped = OPPOSITE_SIDE[side];

        // 1. Flip to the opposite edge when the preferred one is too tight and
        //    the other is roomier.
        if (space[side] < needed && space[flipped] > space[side])
          resolvedSide = flipped;

        // 2. A 288px panel rarely fits beside a trigger on a phone. When neither
        //    horizontal side can hold it, drop to the vertical axis, where the
        //    panel gets the full width instead of a useless slice of it.
        if (!wantsVertical && space[resolvedSide] < naturalWidth)
          resolvedSide = space.bottom >= space.top ? "bottom" : "top";

        // 3. Cap the panel to the room on the side it ended up on, and scroll
        //    the remainder. This is what keeps the trigger visible: without it a
        //    panel taller than the space below has to be pushed back up over the
        //    trigger to fit on screen, hiding the button that was just pressed.
        const onVertical = resolvedSide === "top" || resolvedSide === "bottom";
        const across = onVertical
          ? viewportWidth - padding * 2
          : viewportHeight - padding * 2;
        const along = Math.max(0, space[resolvedSide]);
        contentEl.style.maxWidth = `${Math.max(0, onVertical ? across : along)}px`;
        contentEl.style.maxHeight = `${Math.max(0, onVertical ? along : across)}px`;
        contentEl.style.overflowY =
          contentEl.scrollHeight > contentEl.clientHeight ? "auto" : "";
        contentEl.style.overflowX =
          contentEl.scrollWidth > contentEl.clientWidth ? "auto" : "";
      }

      // Measured after the cap. offsetWidth/Height are the untransformed layout
      // box; getBoundingClientRect would report the shrunken size while the
      // zoom-in entrance animation runs, throwing the alignment off a few pixels.
      const width = contentEl.offsetWidth;
      const height = contentEl.offsetHeight;

      let top = 0;
      let left = 0;

      // 2. Calculate Side
      if (resolvedSide === "top") top = trigger.top - height - sideOffset;
      if (resolvedSide === "bottom") top = trigger.bottom + sideOffset;
      if (resolvedSide === "left") left = trigger.left - width - sideOffset;
      if (resolvedSide === "right") left = trigger.right + sideOffset;

      // 3. Calculate Align
      if (resolvedSide === "top" || resolvedSide === "bottom") {
        if (align === "center")
          left = trigger.left + trigger.width / 2 - width / 2;
        if (align === "start") left = trigger.left;
        if (align === "end") left = trigger.right - width;
      } else {
        if (align === "center")
          top = trigger.top + trigger.height / 2 - height / 2;
        if (align === "start") top = trigger.top;
        if (align === "end") top = trigger.bottom - height;
      }

      // 4. Shift whatever still hangs off an edge back into view — but only
      //    ACROSS the side axis. Alignment is a preference, not a guarantee, so
      //    an align="start"/"end" panel near an edge slides back. Shifting along
      //    the side axis is what used to drag the panel over its own trigger;
      //    the cap in step 3 owns that axis now.
      if (avoidCollisions) {
        if (resolvedSide === "top" || resolvedSide === "bottom") {
          left = clamp(left, padding, viewportWidth - width - padding);
        } else {
          top = clamp(top, padding, viewportHeight - height - padding);
        }
      }

      const nextTop = top + win.scrollY;
      const nextLeft = left + win.scrollX;
      setPlacement((prev) =>
        prev &&
        prev.top === nextTop &&
        prev.left === nextLeft &&
        prev.side === resolvedSide
          ? prev
          : { top: nextTop, left: nextLeft, side: resolvedSide },
      );
    };

    updatePosition();
    win.addEventListener("scroll", updatePosition, true);
    win.addEventListener("resize", updatePosition);
    // The visual viewport shrinks when the mobile keyboard opens over an input
    // inside the panel, and changes on pinch-zoom — neither fires window resize.
    win.visualViewport?.addEventListener("resize", updatePosition);
    win.visualViewport?.addEventListener("scroll", updatePosition);

    // Reposition when the panel or trigger changes size (content loading, the
    // max-height cap applied above, a responsive breakpoint crossing).
    const sizeObserver = new (win.ResizeObserver ?? ResizeObserver)(
      updatePosition,
    );
    sizeObserver.observe(contentRef.current);
    sizeObserver.observe(triggerEl);

    return () => {
      sizeObserver.disconnect();
      win.removeEventListener("scroll", updatePosition, true);
      win.removeEventListener("resize", updatePosition);
      win.visualViewport?.removeEventListener("resize", updatePosition);
      win.visualViewport?.removeEventListener("scroll", updatePosition);
    };
  }, [
    open,
    side,
    align,
    sideOffset,
    avoidCollisions,
    collisionPadding,
    triggerEl,
  ]);

  // Handle Click Outside & Escape Key
  useEffect(() => {
    if (!open) return;

    const handleInteractOutside = (e: MouseEvent | TouchEvent) => {
      if (
        contentRef.current &&
        !contentRef.current.contains(e.target as Node) &&
        triggerEl &&
        !triggerEl.contains(e.target as Node)
      ) {
        setOpen(false);
      }
    };

    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };

    // Listen on the document the trigger actually lives in (supports iframe rendering).
    const doc = contentRef.current?.ownerDocument ?? document;

    doc.addEventListener("mousedown", handleInteractOutside);
    doc.addEventListener("touchstart", handleInteractOutside);
    doc.addEventListener("keydown", handleEscape);

    return () => {
      doc.removeEventListener("mousedown", handleInteractOutside);
      doc.removeEventListener("touchstart", handleInteractOutside);
      doc.removeEventListener("keydown", handleEscape);
    };
  }, [open, setOpen, triggerEl]);

  // triggerEl is null until the trigger commits, which also covers SSR: there
  // is no document to portal into on the server.
  if (!triggerEl || !open) return null;

  // Portal into the trigger's own document (supports iframe rendering).
  const portalTarget = triggerEl.ownerDocument.body;

  return createPortal(
    <div
      ref={contentRef}
      role="dialog"
      className={cn(
        // Below lg the panel competes with the screen for room: smaller type and
        // padding buy back the height that would otherwise have to be scrolled.
        // Width stays a single class so an overriding `className="w-48"` wins at
        // every breakpoint instead of only below lg.
        "absolute z-[9999] w-72 max-w-[calc(100vw-1rem)] p-3 lg:p-4 text-sm lg:text-base outline-none text-popover-foreground bg-popover border border-border rounded-xl shadow-lg",
        // `duration-200` sets transition-duration as well as the animation
        // length, and the browser's default transition-property is `all` — so
        // without `transition-none` the panel would tween its top/left from
        // wherever it last was, sliding across the screen instead of opening in
        // place. Radix/shadcn avoid this the same way: the positioned wrapper
        // never transitions; only the entrance keyframes animate.
        "transition-none animate-in fade-in zoom-in-95 duration-200",
        // Animate from whichever side the panel actually landed on; until it
        // is measured, fall back to the requested side so the classes are stable.
        ENTER_FROM_SIDE[placement?.side ?? side],
        className,
      )}
      style={{
        top: placement?.top ?? 0,
        left: placement?.left ?? 0,
        // Mounted but not yet measured — keep it out of sight rather than
        // flashing it at 0,0. Cleared in the same frame the layout effect runs.
        visibility: placement ? undefined : "hidden",
      }}
      // Stop clicks inside the popover from bubbling up to the document
      onClick={(e) => e.stopPropagation()}
      {...props}
    >
      {children}
    </div>,
    portalTarget,
  );
}

"use client";

import { cn } from "@/lib/utils";
import React, {
  createContext,
  forwardRef,
  useContext,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { getThemeStyles } from "./toggle-group-theme";

// ==========================================
// THEME & CONFIGURATION
// ==========================================
export type ToggleGroupColor =
  | "primary"
  | "indigo"
  | "rose"
  | "emerald"
  | "zinc"
  | (string & {});
/**
 * `segmented` is a pill track whose highlight slides to the pressed item —
 * a view switch (Day / Week / Month). In a single group the pressed item
 * stays pressed when clicked again, and the arrow keys move the choice.
 */
export type ToggleGroupVariant = "default" | "outline" | "ghost" | "segmented";
export type ToggleGroupSize = "sm" | "md" | "lg";
export type ToggleGroupType = "single" | "multiple";

// ==========================================
// CONTEXT
// ==========================================
interface ToggleGroupContextProps {
  type: ToggleGroupType;
  value: string | string[];
  onValueChange: (value: string | string[]) => void;
  variant: ToggleGroupVariant;
  color: ToggleGroupColor;
  size: ToggleGroupSize;
  disabled: boolean;
  theme: Record<string, string>;
  /** Segmented only: the sliding highlight has been placed, so items drop their own. */
  pillReady: boolean;
}

// The segmented track. Inside a `soft` table it takes the table's own well
// (`--tbl-well`), so the tabs and the search field share one tint.
const SEGMENTED_TRACK =
  "bg-[var(--tbl-well,color-mix(in_oklab,var(--primary)_5%,color-mix(in_oklab,var(--foreground)_5%,var(--card))))]";
const SEGMENTED_PILL = "bg-card shadow-sm ring-1 ring-foreground/[0.08]";

const segmentedHeights: Record<ToggleGroupSize, string> = {
  sm: "h-9",
  md: "h-10",
  lg: "h-12",
};

// Layout effects warn during server rendering on older React; the pill is
// only ever measured in the browser anyway.
const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

const ToggleGroupContext = createContext<ToggleGroupContextProps | null>(null);

function useToggleGroup() {
  const context = useContext(ToggleGroupContext);
  if (!context) {
    throw new Error("ToggleGroupItem must be used within a ToggleGroup");
  }
  return context;
}

// ==========================================
// GROUP COMPONENT
// ==========================================
/** Everything both selection modes share. */
interface ToggleGroupBaseProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "defaultValue"> {
  variant?: ToggleGroupVariant;
  color?: ToggleGroupColor;
  size?: ToggleGroupSize;
  disabled?: boolean;
}

/** The default: one item pressed at a time, so the value is a string. */
export interface ToggleGroupSingleProps extends ToggleGroupBaseProps {
  type?: "single";
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

/** `type="multiple"` — value and callback both deal in arrays. */
export interface ToggleGroupMultipleProps extends ToggleGroupBaseProps {
  type: "multiple";
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
}

/**
 * Discriminated on `type`, so a single group hands your callback a `string`
 * and a multiple group hands it a `string[]`, with no cast either way.
 */
export type ToggleGroupProps = ToggleGroupSingleProps | ToggleGroupMultipleProps;

/** The two modes collapsed, which is what the implementation works with. */
type ToggleGroupImplProps = ToggleGroupBaseProps & {
  type?: ToggleGroupType;
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: string | string[]) => void;
};

const ToggleGroupImpl = forwardRef<HTMLDivElement, ToggleGroupImplProps>(
  (
    {
      type = "single",
      value: controlledValue,
      defaultValue,
      onValueChange,
      variant = "default",
      color = "primary",
      size = "md",
      disabled = false,
      className,
      children,
      onKeyDown,
      style: styleProp,
      ...props
    },
    ref,
  ) => {
    const { theme, style } = getThemeStyles(color as string);
    const [uncontrolledValue, setUncontrolledValue] = React.useState<
      string | string[]
    >(defaultValue !== undefined ? defaultValue : type === "single" ? "" : []);

    const isControlled = controlledValue !== undefined;
    const currentValue = isControlled ? controlledValue : uncontrolledValue;

    const handleValueChange = (newValue: string | string[]) => {
      if (!isControlled) setUncontrolledValue(newValue);
      if (onValueChange) onValueChange(newValue);
    };

    const groupRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => groupRef.current as HTMLDivElement);

    // One highlight that slides between items, for a single segmented group.
    // It is measured from the pressed item, so labels of any width work.
    const sliding = variant === "segmented" && type === "single";
    const pillRef = useRef<HTMLSpanElement>(null);
    const placedRef = useRef(false);
    const [pillReady, setPillReady] = useState(false);
    const valueKey = Array.isArray(currentValue)
      ? currentValue.join("|")
      : currentValue;

    useIsomorphicLayoutEffect(() => {
      const group = groupRef.current;
      const pill = pillRef.current;
      if (!sliding || !group || !pill) return;

      const place = () => {
        const active = group.querySelector<HTMLElement>(
          '[data-toggle-item][data-state="on"]',
        );
        if (!active) {
          pill.style.opacity = "0";
          return;
        }
        const g = group.getBoundingClientRect();
        const a = active.getBoundingClientRect();
        // The first placement jumps; every later one slides.
        if (!placedRef.current) pill.style.transition = "none";
        pill.style.width = `${a.width}px`;
        pill.style.height = `${a.height}px`;
        pill.style.transform = `translate(${a.left - g.left - group.clientLeft + group.scrollLeft}px, ${a.top - g.top - group.clientTop}px)`;
        pill.style.opacity = "1";
        if (!placedRef.current) {
          void pill.offsetWidth;
          pill.style.transition = "";
          placedRef.current = true;
          setPillReady(true);
        }
      };

      place();
      const observer = new ResizeObserver(place);
      observer.observe(group);
      group
        .querySelectorAll<HTMLElement>("[data-toggle-item]")
        .forEach((item) => observer.observe(item));
      return () => observer.disconnect();
    }, [sliding, valueKey]);

    // Segmented single groups behave as a radio group: the arrow keys move
    // the choice (and focus) to the next enabled item.
    const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
      onKeyDown?.(event);
      if (event.defaultPrevented || !sliding || disabled) return;
      const keys = ["ArrowRight", "ArrowDown", "ArrowLeft", "ArrowUp", "Home", "End"];
      if (!keys.includes(event.key)) return;
      const items = Array.from(
        groupRef.current?.querySelectorAll<HTMLButtonElement>(
          "[data-toggle-item]:not(:disabled)",
        ) ?? [],
      );
      if (!items.length) return;
      const from = items.findIndex((item) => item === document.activeElement);
      const last = items.length - 1;
      const forward = event.key === "ArrowRight" || event.key === "ArrowDown";
      const next =
        event.key === "Home"
          ? 0
          : event.key === "End"
            ? last
            : forward
              ? from >= last ? 0 : from + 1
              : from <= 0 ? last : from - 1;
      const target = items[next];
      if (!target) return;
      event.preventDefault();
      target.focus();
      const nextValue = target.dataset.value;
      if (nextValue !== undefined) handleValueChange(nextValue);
    };

    return (
      <ToggleGroupContext.Provider
        value={{
          type,
          value: currentValue,
          onValueChange: handleValueChange,
          variant,
          color,
          size,
          disabled,
          theme,
          pillReady: sliding && pillReady,
        }}
      >
        <div
          ref={groupRef}
          role={sliding ? "radiogroup" : "group"}
          className={cn(
            "inline-flex flex-wrap items-center gap-1",
            variant === "default" &&
              "p-1 rounded-xl bg-muted border border-border/50",
            variant === "segmented" &&
              cn(
                "relative flex-nowrap gap-0 rounded-full p-1",
                SEGMENTED_TRACK,
                segmentedHeights[size],
              ),
            className,
          )}
          style={{ ...style, ...styleProp }}
          onKeyDown={handleKeyDown}
          {...props}
        >
          {sliding && (
            <span
              ref={pillRef}
              aria-hidden="true"
              className={cn(
                "pointer-events-none absolute left-0 top-0 rounded-full opacity-0 transition-[transform,width,height] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none",
                SEGMENTED_PILL,
              )}
            />
          )}
          {children}
        </div>
      </ToggleGroupContext.Provider>
    );
  },
);
ToggleGroupImpl.displayName = "ToggleGroup";

/**
 * The implementation is written against the collapsed props; this cast is
 * what hands callers the discriminated pair instead.
 */
export const ToggleGroup = ToggleGroupImpl as React.ForwardRefExoticComponent<
  ToggleGroupProps & React.RefAttributes<HTMLDivElement>
>;

// ==========================================
// ITEM COMPONENT
// ==========================================
export interface ToggleGroupItemProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
}

export const ToggleGroupItem = forwardRef<
  HTMLButtonElement,
  ToggleGroupItemProps
>(({ value, disabled: itemDisabled, className, children, ...props }, ref) => {
  const context = useToggleGroup();
  const {
    type,
    value: groupValue,
    onValueChange,
    variant,
    size,
    disabled: groupDisabled,
    theme,
    pillReady,
  } = context;

  const isDisabled = groupDisabled || itemDisabled;
  const segmented = variant === "segmented";
  const radio = segmented && type === "single";

  // Check if active
  const isActive =
    type === "single"
      ? groupValue === value
      : Array.isArray(groupValue) && groupValue.includes(value);

  const handleToggle = () => {
    if (isDisabled) return;

    if (type === "single") {
      // A segmented choice is a radio: pressing it again keeps it.
      if (radio) {
        if (!isActive) onValueChange(value);
        return;
      }
      onValueChange(isActive ? "" : value);
    } else {
      const currentArray = Array.isArray(groupValue) ? groupValue : [];
      if (isActive) {
        onValueChange(currentArray.filter((v) => v !== value));
      } else {
        onValueChange([...currentArray, value]);
      }
    }
  };

  const sizeStyles = {
    sm: "h-8 px-2.5 text-xs",
    md: "h-10 px-3.5 text-sm",
    lg: "h-12 px-5 text-base",
  };

  const segmentedSizes = {
    sm: "h-full px-3 text-[13px]",
    md: "h-full px-4 text-sm",
    lg: "h-full px-5 text-base",
  };

  const getVariantStyles = () => {
    if (segmented) {
      return cn(
        "relative z-[1] whitespace-nowrap rounded-full text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-primary/60 focus-visible:ring-offset-0",
        segmentedSizes[size],
        isActive && "text-foreground",
        // Until the sliding highlight is measured (and in multiple groups,
        // which have no single highlight) the pressed item paints its own.
        isActive && !pillReady && SEGMENTED_PILL,
      );
    }
    if (isActive) {
      switch (variant) {
        case "outline":
          return cn(theme.border, "shadow-sm");
        case "ghost":
          return cn(theme.text, "bg-muted");
        case "default":
        default:
          return cn(theme.bg, "shadow-md");
      }
    }

    // Inactive states
    switch (variant) {
      case "outline":
        return "border border-border bg-transparent text-muted-foreground hover:bg-muted";
      case "ghost":
        return "bg-transparent text-muted-foreground hover:bg-muted";
      case "default":
      default:
        return "bg-transparent text-muted-foreground hover:bg-muted/50";
    }
  };

  return (
    <button
      ref={ref}
      type="button"
      role={type === "single" ? "radio" : "checkbox"}
      aria-checked={isActive}
      disabled={isDisabled}
      data-toggle-item=""
      data-state={isActive ? "on" : "off"}
      data-value={value}
      // A segmented radio group is one tab stop; the arrow keys move inside it.
      tabIndex={radio ? (isActive || groupValue === "" ? 0 : -1) : undefined}
      onClick={handleToggle}
      className={cn(
        "inline-flex items-center justify-center gap-2 rounded-lg font-medium transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed",
        sizeStyles[size],
        getVariantStyles(),
        className,
      )}
      {...props}
    >
      {children}
    </button>
  );
});
ToggleGroupItem.displayName = "ToggleGroupItem";

"use client";

import React from "react";

const colorThemes: Record<string, Record<string, string>> = {
  // The theme's own accent, so a group follows whatever `--primary` the
  // consumer set — the same contract Button and Input honour.
  primary: {
    bg: "bg-primary text-primary-foreground",
    text: "text-primary",
    border: "border-primary/30 text-primary bg-primary/10",
  },
  indigo: {
    bg: "bg-indigo-500 text-white",
    text: "text-indigo-600 dark:text-indigo-400",
    border:
      "border-indigo-500 text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-500/10",
  },
  rose: {
    bg: "bg-rose-500 text-white",
    text: "text-rose-600 dark:text-rose-400",
    border:
      "border-rose-500 text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-500/10",
  },
  emerald: {
    bg: "bg-emerald-500 text-white",
    text: "text-emerald-600 dark:text-emerald-400",
    border:
      "border-emerald-500 text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-500/10",
  },
  zinc: {
    bg: "bg-zinc-900 text-white dark:bg-zinc-100 dark:text-zinc-900",
    text: "text-zinc-900 dark:text-zinc-100",
    border:
      "border-zinc-900 dark:border-zinc-100 text-zinc-900 dark:text-zinc-100 bg-zinc-100 dark:bg-zinc-800",
  },
};

const hexToRgb = (hex: string) => {
  let cleanHex = hex.replace(/^#/, "");
  if (cleanHex.length === 3)
    cleanHex = cleanHex
      .split("")
      .map((x) => x + x)
      .join("");
  const result = /^([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(cleanHex);
  return result
    ? `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}`
    : "99, 102, 241";
};

export const getThemeStyles = (color: string) => {
  if (color && color.startsWith("#")) {
    const rgb = hexToRgb(color);
    return {
      theme: {
        bg: "bg-[var(--toggle-color)] text-white",
        text: "text-[var(--toggle-color)]",
        border:
          "border-[var(--toggle-color)] text-[var(--toggle-color)] bg-[rgba(var(--toggle-rgb),0.1)]",
      },
      style: {
        "--toggle-color": color,
        "--toggle-rgb": rgb,
      } as React.CSSProperties,
    };
  }
  return { theme: colorThemes[color] || colorThemes.primary, style: {} };
};
